// Generates src/model/trip.gen.ts from schema/trip.schema.json.
// Run with `npm run gen` after changing the schema and commit the result.
import { readFile, writeFile } from 'node:fs/promises'
import { fileURLToPath } from 'node:url'
import { compile, type JSONSchema } from 'json-schema-to-typescript'

const schemaFile = new URL('../schema/trip.schema.json', import.meta.url)
const outFile = new URL('../src/model/trip.gen.ts', import.meta.url)

const banner = `/* eslint-disable */
// Generated by scripts/gen-types.ts from schema/trip.schema.json. Do not edit: run \`npm run gen\`.`

type Node = Record<string, unknown>

// Type-only tweaks on an in-memory copy of the schema (validation is not affected):
// - the root is named Trip;
// - anyOf branches that only list `required` keys (e.g. a stop needs placeId or title) are dropped,
//   otherwise the generator intersects the type with `{ [k: string]: unknown }`;
// - `{ $ref, description }` becomes `{ tsType: <def title>, description }`: same type name, property-specific
//   doc comment, and no numbered duplicates such as Id1, Id2;
// - `allOf: [{ $ref: geo }]` is inlined as lat/lng properties, so Place is one interface (not Geo & Place1);
// - openingHours.weekly gets a weekday-keyed type (the generator ignores propertyNames).
function prepare(schema: Node): Node {
  const copy = structuredClone(schema)
  copy.title = 'Trip'
  const defs = copy.$defs as Record<string, Node & { properties: Record<string, Node> }>
  const visit = (node: unknown): void => {
    if (Array.isArray(node)) return node.forEach(visit)
    if (!node || typeof node !== 'object') return
    const obj = node as Node
    if (Array.isArray(obj.anyOf) && obj.anyOf.every((branch: Node) => Object.keys(branch).join() === 'required')) {
      delete obj.anyOf
    }
    if (Array.isArray(obj.allOf) && obj.allOf.length === 1 && obj.allOf[0].$ref === '#/$defs/geo') {
      delete obj.allOf
      obj.properties = { ...(obj.properties as Node), ...(defs.geo.properties as Node) }
    }
    if (typeof obj.$ref === 'string' && obj.description) {
      obj.tsType = defs[obj.$ref.replace('#/$defs/', '')].title
      delete obj.$ref
    }
    Object.values(obj).forEach(visit)
  }
  visit(copy)
  defs.openingHours.properties.weekly.tsType =
    "Partial<Record<'mon' | 'tue' | 'wed' | 'thu' | 'fri' | 'sat' | 'sun', string[]>>"
  return copy
}

// `patternProperties: { '^x-': {} }` becomes `[k: string]: unknown`, which would accept any typo.
// Narrow it to a template literal index signature: only `x-…` keys are allowed besides the known ones.
const xIndex = /\/\*\*\n(\s*)\* This interface was referenced by `\w+`'s JSON-Schema definition\n\s*\* via the `patternProperty` "\^x-"\.\n\s*\*\/\n\s*\[k: string\]: unknown/g

// Drop the generator's "referenced by `Trip`'s JSON-Schema via the `definition` …" notes.
const definitionNote = /(\n \*)?\n \* This interface was referenced by `Trip`'s JSON-Schema\n \* via the `definition` "\w+"\./g
const emptyComment = /\/\*\*\n \*\/\n/g

export async function generateTypes(): Promise<string> {
  const schema = JSON.parse(await readFile(schemaFile, 'utf8')) as Node
  const ts = await compile(prepare(schema) as JSONSchema, 'Trip', {
    bannerComment: banner,
    additionalProperties: false,
    unreachableDefinitions: true,
    style: { semi: false, singleQuote: true, printWidth: 120 },
  })
  const out = ts
    .replace(definitionNote, '')
    .replace(emptyComment, '')
    .replace(xIndex, (_, indent: string) => {
    const pad = indent.slice(0, -1)
    return `/**\n${indent}* Custom data: any key starting with \`x-\`.\n${indent}*/\n${pad}[k: \`x-\${string}\`]: unknown`
  })
  if (out.includes('[k: string]: unknown')) throw new Error('gen-types: unexpected open index signature in output')
  return out
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  await writeFile(outFile, await generateTypes())
  console.log('wrote src/model/trip.gen.ts')
}
